# Builds the LORINX copy change document (Hebrew, RTL) from structured data.
import html, re, sys

OUT = sys.argv[1]
K = {'replace': 'מחליפים', 'add': 'מוסיפים', 'keep': 'נשאר', 'data': 'מחכה לנתון', 'approve': 'דורש אישור מיוחד', 'remove': 'מורידים'}
PR = {'c': 'קריטי', 'h': 'גבוה', 'm': 'בינוני', 'l': 'נמוך'}

def t(s):
    s = html.escape(s, quote=False)
    s = re.sub(r'\[\[(.+?)\]\]', r'<span class="ph">[\1]</span>', s)
    s = re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', s)
    return s.replace('\n', '<br>')

